        assert(cache !== $substore.cache && root !== $substore.root, 'initCache replaces both local cache objects');
        assert(!('m3-unpersisted' in $substore.cache) && !('m3-unpersisted' in $substore.root), 'unpersisted changes discarded');
        assert($substore.read('m3-host-reload') === 0 && $substore.read('#m3-host-reload') === false, 'durable falsy values reloaded');
        assert(await Promise.resolve('delayed').delay(1) === 'delayed', 'promise delay remains available');
        return {response,cacheReloaded:true,logsAcceptValues:true,processAlive:true};
