    proxies[0].downloadsVerified=passed;
    proxies[0].downloadResults=observations;
    return proxies;
  } finally {
    $substore.write(savedSettings,'settings');
    $substore.write(savedModules,'modules');
    globalThis.Date=OriginalDate;
